<script setup>
import ContentLoading from "@/components/shared/ContentLoading.vue"
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { iso, weekDates, overlaps, blockOf, validateBooking, validateMonthlyRequest, weekStart, isBlocked, quotaFor, personException, bookingDates, bookingWeeks, usedWeeks, selectionWeeks, MAX_VACATION_CHANGES } from '@/services/vacationRules'

const route = useRoute()
const state = ref(null), person = ref(''), year = ref(new Date().getFullYear()), start = ref(''), editing = ref('')
const message = ref(''), busy = ref(false), loading = ref(true), loginOpen = ref(false)
const username = ref(''), password = ref(''), token = ref(''), newName = ref(''), renameId = ref(''), localName = ref(''), newLink = ref('')
const rulesDraft = ref(null), overlapPending = ref(false)
const activeBlock = ref(0), datedDraft = ref(null), exceptionDraft = ref(null)
const cancelTarget = ref(null)
const planMode = ref('blocks')
const isMonthly = computed(() => planMode.value === 'monthly')
const monthlyRequests = computed(() => (state.value?.monthlyRequests || []).filter(r => Number(r.start.slice(0, 4)) === Number(year.value)))
const ownMonthlyRequest = computed(() => monthlyRequests.value.find(r => r.person === person.value))
const monthlyStatus = status => ({ pending: 'Pendiente de aprobación', approved: 'Aprobada por gerencia', rejected: 'No aprobada' }[status] || 'Pendiente de aprobación')
const showFullYear = ref(false), inspectedDay = ref(''), calendarTop = ref(null)
const visibleMonths = computed(() => months.map((name, index) => ({ name, index })).filter(m => isMonthly.value || showFullYear.value || (person.value && Math.floor(m.index / 4) === activeBlock.value)))
const changesLeft = computed(() => Math.max(0, MAX_VACATION_CHANGES - (state.value?.changeCounts?.[`${person.value}:${year.value}`] || 0)))
const myBookings = computed(() => bookings.value.filter(b => b.person === person.value))
const blockLabels = ['Enero - abril', 'Mayo - agosto', 'Septiembre - diciembre']
const quota = block => quotaFor(state.value, person.value, year.value, block)
const personal = computed(() => state.value && personException(state.value, person.value, year.value))
function prepareException() {
  if (!person.value) { message.value = 'Selecciona primero una persona.'; return }
  exceptionDraft.value = JSON.parse(JSON.stringify(personal.value || { person: person.value, year: Number(year.value), quotas: [...state.value.rules.quotas], allowed: [] }))
}
function dayError(day) {
  if (!person.value) return 'Selecciona tu nombre para ver las semanas disponibles.'
  const monday = weekStart(day)
  if (isMonthly.value) return validateMonthlyRequest(state.value, { person: person.value, start: monday })
  if (blockOf(monday) !== activeBlock.value) return 'Esta semana pertenece a otro cuatrimestre.'
  return validateBooking(state.value, { person: person.value, start: monday }, editing.value)
}
const local = computed(() => route.params.local || 'russafa')
const months = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre']
const colors = ['#2563eb', '#9333ea', '#db2777', '#0f766e', '#b45309', '#4f46e5', '#be123c', '#466c20']
const colorNames = ['azul', 'morado', 'rosa', 'verde turquesa', 'ámbar', 'índigo', 'rojo', 'verde oliva']
const personIndex = id => Math.max(0, state.value?.people.findIndex(p => p.id === id) ?? 0)
const name = id => state.value?.people.find(p => p.id === id)?.name || 'Persona'
const color = id => colors[personIndex(id)] || `hsl(${(personIndex(id) * 137.508) % 360} 65% 35%)`
const colorName = id => colorNames[personIndex(id)] || `tono ${personIndex(id) + 1}`
const initials = id => name(id).split(/\s+/).filter(Boolean).map(part => part[0]).join('').slice(0, 2).toUpperCase()
const isMyDay = day => !!person.value && dayBookings(day).some(b => b.person === person.value)
function dayStyle(day) {
  if (selection.value.includes(day)) return { background: color(person.value), color: '#fff', borderColor: color(person.value) }
  const people = [...new Set(dayBookings(day).map(b => b.person))]
  if (!people.length) return {}
  const first = isMyDay(day) ? person.value : people[0]
  const fill = id => `color-mix(in srgb, ${color(id)} ${id === person.value ? '38%' : '22%'}, white)`
  const background = people.length === 1 ? fill(first) : `linear-gradient(135deg, ${people.map((id, i) => `${fill(id)} ${i / people.length * 100}% ${(i + 1) / people.length * 100}%`).join(', ')})`
  return { background, borderColor: color(first), borderWidth: isMyDay(day) ? '2px' : '1px' }
}
const bookings = computed(() => state.value?.bookings.filter(b => Number(b.start.slice(0, 4)) === Number(year.value)).sort((a, b) => a.start.localeCompare(b.start)) || [])
const selectedWeeks = computed(() => isMonthly.value ? 4 : start.value ? selectionWeeks(state.value, person.value, start.value, editing.value) : activeBlock.value === 1 ? 2 : 1)
const calendarRequests = computed(() => isMonthly.value ? monthlyRequests.value.filter(r => r.status !== 'rejected') : bookings.value)
const conflicts = computed(() => start.value ? calendarRequests.value.filter(b => b.id !== editing.value && b.person !== person.value && overlaps(b, { start: start.value, weeks: selectedWeeks.value })) : [])
const selection = computed(() => weekDates(start.value, selectedWeeks.value))
const selectionError = computed(() => state.value && start.value ? isMonthly.value ? validateMonthlyRequest(state.value, { person: person.value, start: start.value }) : validateBooking(state.value, { person: person.value, start: start.value }, editing.value) : '')
const used = block => usedWeeks(state.value, person.value, year.value, block)
const dayBookings = day => calendarRequests.value.filter(b => bookingDates(b).includes(day))
const completed = computed(() => person.value && [0, 1, 2].every(i => used(i) >= quota(i)))
function nextPending() {
  if (!state.value || !person.value) return
  const next = [0, 1, 2].find(i => used(i) < quota(i))
  if (next !== undefined) activeBlock.value = next
}
const blocked = day => isBlocked(state.value, day, person.value)
function days(month) {
  const first = new Date(Date.UTC(Number(year.value), month, 1, 12))
  const offset = (first.getUTCDay() + 6) % 7
  return [...Array(offset).fill(null), ...Array.from({ length: new Date(Date.UTC(Number(year.value), month + 1, 0)).getUTCDate() }, (_, i) => iso(new Date(Date.UTC(Number(year.value), month, i + 1, 12))))]
}
async function request(body) {
  const res = await fetch(`/.netlify/functions/vacations?local=${encodeURIComponent(local.value)}`, { method: body ? 'POST' : 'GET', headers: { 'Content-Type': 'application/json', ...(token.value ? { Authorization: `Bearer ${token.value}` } : {}) }, ...(body ? { body: JSON.stringify(body) } : {}) })
  let data
  try { data = await res.json() } catch { throw new Error('No se pudo cargar el servicio de vacaciones. Actualiza la página y vuelve a intentarlo.') }
  if (!res.ok) { if (res.status === 401 || res.status === 403) token.value = ''; const error = new Error(data.error); error.conflicts = data.conflicts; throw error }
  return data
}
async function load() {
  try { state.value = await request(); if (person.value && !state.value.people.some(p => p.id === person.value)) person.value = '' }
  catch (e) { message.value = e.message } finally { loading.value = false }
}
async function action(body, success = 'Cambios guardados.') {
  if (busy.value) return
  busy.value = true; message.value = ''; overlapPending.value = false
  try {
    const data = await request(body)
    if (body.action === 'login') { token.value = data.token; password.value = ''; loginOpen.value = false }
    else if (body.action === 'createLocal') { newLink.value = `${window.location.origin}/ruzafa-impresora/vacaciones/${data.id}`; localName.value = '' }
    else { state.value = data; if (['book', 'cancelBooking', 'deleteBooking', 'monthlyRequest', 'cancelMonthly'].includes(body.action)) { start.value = ''; editing.value = ''; cancelTarget.value = null; inspectedDay.value = ''; showFullYear.value = false; if (!isMonthly.value) nextPending(); await nextTick(); calendarTop.value?.scrollIntoView({ behavior: 'smooth', block: 'start' }) } }
    message.value = success
  } catch (e) { message.value = e.message; overlapPending.value = !!e.conflicts; if (e.conflicts || body.action === 'book') await load() }
  finally { busy.value = false }
}
const reserve = () => action({ action: isMonthly.value ? 'monthlyRequest' : 'book', person: person.value, start: start.value, weeks: selectedWeeks.value, id: editing.value || undefined, confirmOverlap: conflicts.value.length > 0 }, isMonthly.value ? 'Consulta enviada. Tus cuatro semanas juntas están pendientes de aprobación; tu plan por cuatrimestres se conserva.' : conflicts.value.length ? 'Alternativa guardada, pendiente de coordinar con el equipo y gerencia.' : 'Vacaciones guardadas. Continúa con el siguiente bloque pendiente.')
async function choose(day) {
  cancelTarget.value = null; inspectedDay.value = day; message.value = ''; start.value = ''; overlapPending.value = false
  if (!person.value) return
  const block = blockOf(weekStart(day))
  if (!isMonthly.value && block !== activeBlock.value) { activeBlock.value = block; await nextTick() }
  inspectedDay.value = day
  start.value = weekStart(day)
}
async function edit(b) { planMode.value = 'blocks'; person.value = b.person; await nextTick(); activeBlock.value = blockOf(b.start); await nextTick(); start.value = b.start; editing.value = b.id; window.scrollTo({ top: 0, behavior: 'smooth' }) }
function openRules() { rulesDraft.value = JSON.parse(JSON.stringify(state.value.rules)) }
watch([person, year, activeBlock], () => { start.value = ''; editing.value = ''; inspectedDay.value = ''; cancelTarget.value = null; exceptionDraft.value = null; overlapPending.value = false })
watch([person, year], () => { showFullYear.value = false; nextPending() })
watch(planMode, () => { start.value = ''; editing.value = ''; cancelTarget.value = null; inspectedDay.value = ''; showFullYear.value = false })
watch(local, () => { state.value = null; person.value = ''; rulesDraft.value = null; loading.value = true; load() })
let timer
onMounted(() => { load(); timer = setInterval(load, 30000) })
onUnmounted(() => clearInterval(timer))
</script>

<template>
  <main class="vacations">
    <header><div><RouterLink to="/ruzafa-impresora" class="back">← Impresora Russafa</RouterLink><p class="eyebrow">PLANIFICACIÓN DEL EQUIPO</p><h1>Calendario de vacaciones</h1><p>{{ state?.name || 'Tu local' }} · Organiza tus semanas con tiempo.</p></div><button @click="token ? token = '' : loginOpen = !loginOpen">{{ token ? 'Cerrar gerencia' : 'Acceso gerentes' }}</button></header>
    <p v-if="message" role="status" class="notice">{{ message }}</p>
    <form v-if="loginOpen" class="panel login" @submit.prevent="action({ action: 'login', username, password }, 'Sesión de gerencia iniciada.')"><h2>Acceso de gerencia</h2><label>Usuario<input v-model="username" autocomplete="username" required></label><label>Contraseña<input v-model="password" type="password" autocomplete="current-password" required></label><button :disabled="busy" class="primary">Entrar</button></form>
    <ContentLoading v-if="loading" variant="inline" />
    <button v-if="!state && !loading" @click="load">Volver a intentar</button>
    <template v-if="state">
      <nav class="plan-switch" aria-label="Forma de organizar las vacaciones"><button :class="{ active: !isMonthly }" :aria-pressed="!isMonthly" :disabled="busy" @click="planMode = 'blocks'">Por cuatrimestres</button><button :class="{ active: isMonthly }" :aria-pressed="isMonthly" :disabled="busy" @click="planMode = 'monthly'">Mes completo</button></nav>
      <p v-if="!isMonthly" class="plan-example">El año se divide en <strong>3 cuatrimestres</strong>: enero-abril, <strong>1 semana</strong>; mayo-agosto, <strong>2 semanas seguidas</strong>; septiembre-diciembre, <strong>1 semana</strong>.</p>
      <p v-else class="warning">Consulta de un mes: <strong>4 semanas juntas, 28 días seguidos</strong>. Es una alternativa más difícil de encajar y <strong>no está garantizada</strong>. Gerencia estudiará si puede aprobarla. Tu plan por cuatrimestres se conserva.</p>
      <section class="panel controls"><label>¿Quién eres?<select v-model="person" :disabled="busy"><option value="">Selecciona tu nombre</option><option v-for="p in state.people" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>Año<input v-model="year" :disabled="busy" type="number" min="2020" max="2100"></label><button @click="load">Actualizar calendario</button><p>Pulsa un día disponible para escoger su semana completa, de lunes a domingo. El calendario se actualiza cada 30 segundos.</p></section>

      <section v-if="person" class="identity-color" :style="{ '--person-color': color(person) }" role="status"><span class="identity-swatch" aria-hidden="true">{{ initials(person) }}</span><div><strong>{{ name(person) }}, tu color es {{ colorName(person) }}</strong><p>Busca este color y tus iniciales <b>{{ initials(person) }}</b> en el calendario.</p></div></section>
      <div ref="calendarTop" class="calendar-heading"><div><p v-if="person && !isMonthly" class="eyebrow">PASO {{ activeBlock + 1 }} DE 3</p><h2>{{ showFullYear ? 'Calendario completo' : isMonthly ? 'Mes completo' : person ? blockLabels[activeBlock] : 'Elige tu nombre para empezar' }}</h2></div><button v-if="!isMonthly" :aria-pressed="showFullYear" @click="showFullYear = !showFullYear">{{ showFullYear ? 'Volver a mi paso' : 'Ver calendario completo' }}</button></div>
      <nav v-if="person && !isMonthly" class="step-progress" aria-label="Progreso de vacaciones"><button v-for="(label, i) in blockLabels" :key="label" :class="{ current: activeBlock === i, done: used(i) >= quota(i) }" :disabled="busy" @click="activeBlock = i; showFullYear = false"><strong>{{ used(i) >= quota(i) ? '✓' : i + 1 }}</strong><span>{{ label }}</span></button></nav>
      <p v-if="isMonthly && person" class="block-info">{{ name(person) }}, toca la primera semana: seleccionaremos 28 días seguidos para consultar su aprobación.</p>
      <p v-if="!isMonthly" class="block-info" role="status"><template v-if="!person">Elige tu nombre para empezar.</template><template v-else-if="completed">Tus vacaciones están completas.</template><template v-else><strong>{{ name(person) }}</strong>, toca una fecha para elegir {{ activeBlock === 1 && quota(activeBlock) - used(activeBlock) >= 2 ? 'tus dos semanas seguidas' : 'tu semana' }} de <strong>{{ blockLabels[activeBlock] }}</strong>.</template></p>

      <section v-if="cancelTarget" class="floating-confirm" role="region" aria-label="Confirmar borrado"><div><strong>{{ cancelTarget.monthly ? '¿Retirar esta consulta mensual?' : '¿Borrar estas vacaciones y elegir otras fechas?' }}</strong><p>{{ cancelTarget.start }} → {{ bookingDates(cancelTarget).at(-1) }}</p><p>{{ token ? 'Este cambio de gerencia no consume intentos.' : 'Usarás 1 cambio. Después te quedarán ' + Math.max(0, changesLeft - 1) + '.' }}</p><p v-if="message" role="status">{{ message }}</p></div><button class="primary" :disabled="busy" @click="action({ action: cancelTarget.monthly ? 'cancelMonthly' : 'cancelBooking', id: cancelTarget.id, person }, 'Vacaciones borradas. Elige las nuevas fechas en el calendario.')">{{ busy ? 'Borrando...' : 'Sí, borrar y volver a elegir' }}</button><button :disabled="busy" @click="cancelTarget = null">Cancelar</button></section>
      <p v-if="personal" class="notice">Tienes condiciones personales autorizadas por gerencia para {{ year }}. Los días autorizados se muestran disponibles y tus cuotas aparecen arriba.</p>
      <p v-if="completed && !isMonthly" class="notice" role="status">Ya has completado tus vacaciones de este año. Puedes verlas con tu color en el calendario.</p>
      <section v-if="start" class="floating-confirm" role="region" aria-label="Confirmar vacaciones" aria-live="polite"><div><strong>{{ name(person) }}, ¿quieres guardar {{ isMonthly ? 'esta consulta de cuatro semanas juntas' : selectedWeeks === 2 ? 'estas dos semanas seguidas' : 'esta semana' }}?</strong><p>{{ start }} → {{ selection.at(-1) }} · {{ selectedWeeks * 7 }} días seguidos</p><p v-if="isMonthly && ownMonthlyRequest" class="warning">Ya tienes una consulta: al enviar estas fechas se reemplazará y volverá a quedar pendiente. {{ token ? 'Gerencia no consume cambios.' : 'Se usará 1 de tus cambios disponibles.' }}</p><p v-if="isMonthly" class="warning">Solo es una consulta pendiente de aprobación. No sustituye tus fechas por cuatrimestres.</p><p v-if="conflicts.length" class="warning">Estas fechas las ha solicitado {{ [...new Set(conflicts.map(b => name(b.person)))].join(', ') }}. Puedes pedirlas también para valorar opciones, pero deberéis hablarlo con gerencia. Se guardarán como alternativa pendiente de coordinar.</p><p v-if="selectionError" class="warning">{{ selectionError }}</p><p v-if="message" role="status">{{ message }}</p></div><button class="primary" :disabled="busy || !!selectionError" @click="reserve">{{ busy ? 'Guardando...' : isMonthly ? 'Enviar consulta de 4 semanas' : conflicts.length ? 'Guardar alternativa y continuar' : 'Aceptar y continuar' }}</button><button :disabled="busy" @click="start = ''; editing = ''; inspectedDay = ''">Cancelar</button></section>
      <section v-if="inspectedDay && !start" class="floating-confirm" role="status"><div><strong>{{ inspectedDay }}</strong><p v-if="dayBookings(inspectedDay).length">Esta fecha la ha solicitado {{ [...new Set(dayBookings(inspectedDay).map(b => name(b.person)))].join(', ') }}.</p><p v-else>No hay solicitudes para este día.</p><p>Elige tu nombre para solicitar vacaciones.</p></div><button @click="inspectedDay = ''">Cerrar</button></section>
      <div class="legend"><span>□ Disponible</span><span class="muted">▧ Bloqueado</span><span class="selected-key" :style="person ? { color: color(person) } : {}">■ Tu selección</span><span v-for="p in state.people" :key="p.id" :class="{ 'legend-me': p.id === person }" :style="{ color: color(p.id) }">● {{ p.name }}{{ p.id === person ? ' (tú)' : '' }}</span></div>
      <section class="calendar"><article v-for="{ name: month, index: m } in visibleMonths" :key="month" class="month"><h2>{{ month }} <small>{{ year }}</small></h2><div class="days"><span v-for="d in ['L', 'M', 'X', 'J', 'V', 'S', 'D']" :key="d" class="weekday">{{ d }}</span><template v-for="(day, i) in days(m)" :key="i"><span v-if="!day"></span><button v-else :disabled="busy" :style="dayStyle(day)" :class="{ 'my-day': isMyDay(day), unavailable: !!dayError(day), blocked: blocked(day), selected: selection.includes(day), occupied: dayBookings(day).length }" :aria-label="`${day}${blocked(day) ? ', bloqueado' : ''}${dayBookings(day).map(b => ', ' + name(b.person)).join('')}`" :aria-pressed="selection.includes(day)" :title="dayError(day) || 'Semana disponible de lunes a domingo'" @click="choose(day)"><span>{{ Number(day.slice(8)) }}</span><small v-if="isMyDay(day) || selection.includes(day)" class="my-initials" :style="{ background: color(person) }" aria-hidden="true">{{ initials(person) }}</small><div class="dots"><i v-for="b in dayBookings(day)" :key="b.id" :style="{ background: color(b.person) }"></i></div></button></template></div></article></section>
      <section v-if="!isMonthly && person && myBookings.length" class="panel my-vacations"><h2>Tus vacaciones</h2><p>{{ token ? 'Gerencia: puedes cambiar las fechas sin límite.' : 'Te quedan ' + changesLeft + ' de 10 cambios este año.' }}</p><article v-for="b in myBookings" :key="b.id" class="booking"><span>{{ b.start }} → {{ bookingDates(b).at(-1) }}</span><button :disabled="busy || (!token && changesLeft === 0)" @click="start = ''; cancelTarget = b">Borrar y elegir otras fechas</button></article><p v-if="!token && changesLeft === 0">Para otro cambio, contacta con gerencia.</p></section>
      <section v-if="isMonthly" class="panel"><h2>Consultas de cuatro semanas juntas</h2><p>Las consultas son alternativas al plan por cuatrimestres. Solo gerencia decide su estado; no cambian automáticamente las vacaciones del plan habitual.</p><p v-if="!monthlyRequests.length">Aún no hay consultas para este año.</p><article v-for="r in monthlyRequests" :key="r.id" class="booking"><strong :style="{ color: color(r.person) }">{{ name(r.person) }}</strong><span>{{ r.start }} → {{ bookingDates(r).at(-1) }}</span><small class="warning">{{ monthlyStatus(r.status) }}</small><template v-if="token"><button :disabled="busy" @click="action({ action: 'reviewMonthly', id: r.id, status: 'approved' })">Aprobar alternativa</button><button :disabled="busy" @click="action({ action: 'reviewMonthly', id: r.id, status: 'rejected' })">No aprobar</button><button :disabled="busy" @click="action({ action: 'reviewMonthly', id: r.id, status: 'pending' })">Reabrir consulta</button></template><button v-if="token || r.person === person" :disabled="busy || (!token && changesLeft === 0)" @click="start = ''; cancelTarget = { ...r, monthly: true }">Retirar consulta</button></article><p v-if="person">Te quedan {{ changesLeft }} de 10 cambios este año. Reemplazar o retirar una consulta consume un cambio.</p></section>
      <section v-if="!isMonthly" class="panel"><h2>Semanas del equipo · {{ year }}</h2><p v-if="!bookings.length">Todavía no hay semanas elegidas. Selecciona tu nombre para empezar.</p><article v-for="b in bookings" :key="b.id" class="booking"><strong :style="{ color: color(b.person) }">{{ name(b.person) }}</strong><small>{{ bookingWeeks(b) === 2 ? '2 semanas seguidas' : '1 semana' }}</small><span>{{ b.start }} → {{ bookingDates(b).at(-1) }}</span><small v-if="bookings.some(other => other.id !== b.id && other.person !== b.person && overlaps(b, other))" class="warning">Coincidencia · pendiente de coordinar</small><template v-if="token"><button @click="edit(b)">Cambiar fecha</button><button :disabled="busy" @click="action({ action: 'deleteBooking', id: b.id }, 'Semana eliminada.')">Eliminar</button></template></article></section>
      <section v-if="token" class="panel management"><h2>Gestionar {{ state.name }}</h2><p>Los cambios se guardan para este local. Las reservas existentes se conservan si cambias las condiciones; revisa sus fechas después.</p><form @submit.prevent="action({ action: 'person', id: renameId || undefined, name: newName })"><h3>Personal</h3><label>Agregar o renombrar<select v-model="renameId"><option value="">Nueva persona</option><option v-for="p in state.people" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>Nombre<input v-model="newName" maxlength="80" required></label><button :disabled="busy">Guardar persona</button></form>
      <button @click="openRules">Editar condiciones y fechas bloqueadas</button><form v-if="rulesDraft" @submit.prevent="action({ action: 'rules', rules: rulesDraft })"><h3>Semanas por bloque de cuatro meses</h3><label v-for="(_, i) in rulesDraft.quotas" :key="i">{{ ['Enero–abril', 'Mayo–agosto', 'Septiembre–diciembre'][i] }}<input v-model.number="rulesDraft.quotas[i]" type="number" min="0" max="18" required></label><h3>Bloqueos anuales (mes-día)</h3><div v-for="(range, i) in rulesDraft.blocked" :key="i" class="range"><label>Desde<input v-model="range[0]" placeholder="03-01" pattern="[0-9]{2}-[0-9]{2}" required></label><label>Hasta<input v-model="range[1]" placeholder="03-31" pattern="[0-9]{2}-[0-9]{2}" required></label><button type="button" @click="rulesDraft.blocked.splice(i, 1)">Quitar</button></div><button type="button" @click="rulesDraft.blocked.push(['', ''])">Añadir bloqueo</button><button class="primary" :disabled="busy">Guardar condiciones</button></form>
      <div class="admin-extras"><h3>Bloquear días concretos</h3><p>Estos bloqueos afectan a todo el equipo. Una autorización personal puede desbloquearlos solo para esa persona.</p><button @click="datedDraft = JSON.parse(JSON.stringify(state.rules.datedBlocked || []))">Cargar bloqueos guardados</button><form v-if="datedDraft" @submit.prevent="action({ action: 'datedBlocks', ranges: datedDraft })"><div v-for="(range, i) in datedDraft" :key="i" class="range"><label>Desde<input v-model="range[0]" type="date" required></label><label>Hasta<input v-model="range[1]" type="date" required></label><button type="button" @click="datedDraft.splice(i, 1)">Quitar</button></div><button type="button" @click="datedDraft.push(['', ''])">Añadir días bloqueados</button><button :disabled="busy">Guardar bloqueos concretos</button></form>
      <h3>Autorización personal: {{ person ? name(person) : 'Selecciona una persona arriba' }}</h3><p>Permite fechas bloqueadas y ajusta cuántas semanas puede escoger esta persona en {{ year }}. Para autorizar un mes completo, añade su primer y último día y aumenta su cuota. Se mantienen las semanas de lunes a domingo y los avisos de coincidencias.</p><button :disabled="!person" @click="prepareException">Configurar autorización personal</button><form v-if="exceptionDraft" @submit.prevent="action({ action: 'exception', exception: exceptionDraft })"><label v-for="(label, i) in blockLabels" :key="i">{{ label }}: semanas permitidas<input v-model.number="exceptionDraft.quotas[i]" type="number" min="0" max="18" required></label><div v-for="(range, i) in exceptionDraft.allowed" :key="i" class="range"><label>Permitir desde<input v-model="range[0]" type="date" required></label><label>Hasta<input v-model="range[1]" type="date" required></label><button type="button" @click="exceptionDraft.allowed.splice(i, 1)">Quitar</button></div><button type="button" @click="exceptionDraft.allowed.push(['', ''])">Añadir intervalo autorizado</button><button :disabled="busy">Guardar autorización</button><button type="button" :disabled="busy" @click="action({ action: 'exception', exception: exceptionDraft, remove: true })">Restablecer condiciones generales</button></form></div>
      <form @submit.prevent="action({ action: 'createLocal', name: localName }, 'Local creado. Comparte su enlace después de añadir el personal.')"><h3>Crear otro local</h3><label>Nombre del local<input v-model="localName" maxlength="80" required></label><button :disabled="busy">Crear y generar enlace</button><p v-if="newLink">Enlace del nuevo local: <a :href="newLink">{{ newLink }}</a></p><p>Cada enlace muestra únicamente el personal y las vacaciones de ese local. Abre el enlace e inicia sesión como gerente para añadir su equipo.</p></form></section>
